#!/usr/bin/env python3
"""Install Textivo v12 native animated SVG export into ~/textivo."""
from pathlib import Path
import base64, shutil, sys

ROOT = Path.home() / "textivo"
APP = ROOT / "js" / "app.js"
INDEX = ROOT / "index.html"
SW = ROOT / "sw.js"
MARKER = "TEXTIVO_SVG_EXPORT_V12"
SVG_MODULE = base64.b64decode("").decode("utf-8")

if not APP.is_file():
    print("ERROR: ~/textivo/js/app.js not found. No files changed.")
    sys.exit(1)
source = APP.read_text(encoding="utf-8")
if MARKER in source:
    print("Textivo v12 SVG export is already installed.")
    sys.exit(0)
if 'window.TEXTIVO_BUILD = "v11";' not in source:
    print('ERROR: Expected Textivo v11. No files changed.')
    sys.exit(2)
start = source.find('$("svgBtn").addEventListener("click",')
end = source.find('$("pngBtn").addEventListener("click"', start)
if start < 0 or end < 0 or "function escapeXML" not in source[start:end]:
    print("ERROR: Could not safely locate the old SVG export block. No files changed.")
    sys.exit(3)
backup = APP.with_name("app.js.v11-backup")
if not backup.exists():
    shutil.copy2(APP, backup)
updated = source[:start] + SVG_MODULE + chr(10) + '$("svgBtn").addEventListener("click", exportTextivoSVG); ' + source[end:]
updated = updated.replace('window.TEXTIVO_BUILD = "v11";', 'window.TEXTIVO_BUILD = "v12";', 1)
APP.write_text(updated, encoding="utf-8")
if INDEX.exists():
    html = INDEX.read_text(encoding="utf-8").replace("css/style.css?v=11","css/style.css?v=12").replace("js/app.js?v=11","js/app.js?v=12").replace("sw.js?v=10","sw.js?v=12")
    INDEX.write_text(html, encoding="utf-8")
if SW.exists():
    cache = SW.read_text(encoding="utf-8").replace("textivo-v11","textivo-v12").replace("?v=11","?v=12").replace("?v=10","?v=12")
    SW.write_text(cache, encoding="utf-8")
print("PATCH APPLIED: Textivo v12 native animated SVG export")
print("Backup:", backup)
print("Output: native SVG text/tspan and embedded SMIL; no raster images or external dependencies.")
